 def test_missing_runtime_evidence_is_rejected_without_defaults(self):
  with tempfile.TemporaryDirectory() as td:
   root=Path(td); c,b,r,a=self.fixture(root)
   with self.assertRaisesRegex(RuntimeError,'runtime supplement missing'): build_adapter_config(contract=c,blueprint=b,blueprint_review=r,local_authorization=a,runtime_supplement={})
 def test_adapter_budget_is_derived_from_human_authorization(self):
  with tempfile.TemporaryDirectory() as td:
   root=Path(td); c,b,r,a=self.fixture(root); cfg=build_adapter_config(contract=c,blueprint=b,blueprint_review=r,local_authorization=a,runtime_supplement=self.runtime()); self.assertEqual(cfg['resource_cap']['gpu_hours'],2.0); self.assertEqual(cfg['resource_cap']['episodes'],48); self.assertEqual(cfg['reopen_lineage']['authorized_max_provider_calls'],60); self.assertTrue(cfg['reopen_lineage']['adapter_cannot_authorize_execution'])
 def test_runtime_episode_claim_cannot_exceed_authorization(self):
  with tempfile.TemporaryDirectory() as td:
   root=Path(td); c,b,r,a=self.fixture(root); runtime=self.runtime(); runtime['scope']['worst_case_environment_episodes']=49
   with self.assertRaisesRegex(RuntimeError,'episodes exceed'): build_adapter_config(contract=c,blueprint=b,blueprint_review=r,local_authorization=a,runtime_supplement=runtime)
 def test_real_compiler_block_is_preserved_and_never_creates_lease(self):
  with tempfile.TemporaryDirectory() as td:
   root=Path(td); c,b,r,a=self.fixture(root); out=compile_reopened_pre_experiment(contract=c,blueprint=b,blueprint_review=r,local_authorization=a,runtime_supplement=self.runtime(),data_root=root); self.assertTrue(validate_reopened_pre_experiment(out)); self.assertIn(out['status'],{PASS_STATUS,BLOCK_STATUS}); self.assertFalse(out['effective_execution_authorized']); self.assertFalse((root/'experiment-authority').exists())
 def test_compiler_pass_still_requires_experiment_lease(self):
  with tempfile.TemporaryDirectory() as td:
   root=Path(td); c,b,r,a=self.fixture(root); fake={"status":"pass","execution_authorized":True,"passed_gates":8,"gate_count":8,"blockers":[],"config_hash":"x"}
   with patch('research_pipeline.reopened_pre_experiment_adapter.compile_pre_experiment_card',return_value=fake): out=compile_reopened_pre_experiment(contract=c,blueprint=b,blueprint_review=r,local_authorization=a,runtime_supplement=self.runtime(),data_root=root)
   self.assertEqual(out['status'],PASS_STATUS); self.assertTrue(out['compiler_execution_ready']); self.assertFalse(out['effective_execution_authorized']); self.assertTrue(out['experiment_lease_required']); self.assertTrue(out['automatic_lease_acquisition_forbidden']); self.assertFalse((root/'experiment-authority').exists())
 def test_public_projection_never_exposes_compiler_card_or_runtime_paths(self):
  with tempfile.TemporaryDirectory() as td:
   root=Path(td); c,b,r,a=self.fixture(root); fake={"status":"blocked","execution_authorized":False,"passed_gates":7,"gate_count":8,"blockers":["runtime-secret-path:/tmp/x"],"config_hash":"x"}
   with patch('research_pipeline.reopened_pre_experiment_adapter.compile_pre_experiment_card',return_value=fake): out=compile_reopened_pre_experiment(contract=c,blueprint=b,blueprint_review=r,local_authorization=a,runtime_supplement=self.runtime(),data_root=root)
   publish_reopened_pre_experiment(root,out); pub=public_reopened_pre_experiment(root,c['contract_id']); text=json.dumps(pub); self.assertEqual(pub['compiler_blocker_count'],1); self.assertNotIn('runtime-secret-path',text); self.assertNotIn('pre_experiment_card',text)

